import{f as t,o as s,c as a,a6 as i}from"./chunks/framework.Dd1qhYRL.js";const k=JSON.parse('{"title":"noorm init","description":"","frontmatter":{},"headers":[],"relativePath":"cli/init.md","filePath":"cli/init.md"}'),n={name:"cli/init.md"};function o(d,e,r,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="noorm-init" tabindex="-1">noorm init <a class="header-anchor" href="#noorm-init" aria-label="Permalink to “noorm init”">​</a></h1><p>Create a noorm project in the current repository: the <code>.noorm/</code> state folder and the <code>db/</code> folder that holds your schema.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌  noorm init</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>●  Using existing identity: Alice Cooper &lt;alice@example.com&gt;</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>◇  Done</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└  noorm initialized.</span></span>
<span class="line"><span>  Created:</span></span>
<span class="line"><span>    db/sql/.gitkeep</span></span>
<span class="line"><span>    db/changes/.gitkeep</span></span>
<span class="line"><span>    db/AGENTS.md</span></span>
<span class="line"><span>    db/CLAUDE.md</span></span>
<span class="line"><span>    .noorm/.gitignore</span></span>
<span class="line"><span>    .noorm/settings.yml</span></span>
<span class="line"><span>    .noorm/state/state.enc</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── .gitignore               # gains &quot;# noorm&quot; and &quot;.noorm/state/&quot;</span></span>
<span class="line"><span>├── .noorm/</span></span>
<span class="line"><span>│   ├── .gitignore           # state/</span></span>
<span class="line"><span>│   ├── settings.yml         # paths: ./db/sql, ./db/changes</span></span>
<span class="line"><span>│   └── state/state.enc      # configs and secrets, encrypted with your identity key</span></span>
<span class="line"><span>└── db/</span></span>
<span class="line"><span>    ├── AGENTS.md            # points coding agents at the /noorm skill</span></span>
<span class="line"><span>    ├── CLAUDE.md            # imports AGENTS.md</span></span>
<span class="line"><span>    ├── changes/</span></span>
<span class="line"><span>    └── sql/</span></span></code></pre></div><p><code>db/AGENTS.md</code> also states that <code>sql/</code> is the schema&#39;s current state and <code>changes/</code> brings existing databases up to it. It points data modeling at <a href="/modeling/">ignatius</a> and its <a href="/modeling/modeling-skill.html"><code>/ignatius-modeling</code> skill</a>, and holds a marker comment for your own steering. <code>db/CLAUDE.md</code> is one line, <code>@AGENTS.md</code>. Without <code>--yes</code>, <code>init</code> prompts for a name and email when no identity exists yet.</p><h2 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to “Flags”">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--force</code>, <code>-f</code></td><td>Initialize a folder that already has <code>.noorm/</code>. Resets <code>settings.yml</code> to defaults and keeps its <code>paths</code></td></tr><tr><td><code>--here</code></td><td>Initialize the directory you launched from, ignoring a parent <code>.noorm/</code></td></tr><tr><td><code>--yes</code>, <code>-y</code></td><td>Skip prompts. Needs an identity in <code>~/.noorm/</code>. <code>NOORM_YES=1</code> is the same</td></tr></tbody></table><p><code>noorm init</code> has no <code>--json</code> flag.</p><h2 id="which-folder-becomes-the-project-root" tabindex="-1">Which folder becomes the project root? <a class="header-anchor" href="#which-folder-becomes-the-project-root" aria-label="Permalink to “Which folder becomes the project root?”">​</a></h2><p>Every <code>noorm</code> command walks up from the current directory to the nearest <code>.noorm/</code> and runs there. <code>init</code> follows the same rule, so it targets the parent project unless you say otherwise.</p><table tabindex="0"><thead><tr><th>Invocation</th><th>Project root</th></tr></thead><tbody><tr><td><code>noorm init</code></td><td>Nearest parent holding <code>.noorm/</code>; the current directory when none does</td></tr><tr><td><code>noorm init --here</code></td><td>The directory you launched from. Nests a project inside another, such as <code>packages/db/</code></td></tr><tr><td><code>noorm -c packages/db init</code></td><td><code>packages/db</code>, with no walk up. <code>-c</code> must come before <code>init</code></td></tr></tbody></table><h2 id="what-happens-to-an-existing-project" tabindex="-1">What happens to an existing project? <a class="header-anchor" href="#what-happens-to-an-existing-project" aria-label="Permalink to “What happens to an existing project?”">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td><code>.noorm/</code> exists, no <code>--force</code></td><td><code>Error: noorm project already initialized at &lt;path&gt;. Use --force to reinitialize.</code>, exit 1</td></tr><tr><td><code>--force</code></td><td><code>settings.yml</code> resets to defaults except <code>paths</code>. <code>db/AGENTS.md</code> and <code>db/CLAUDE.md</code> are written only when absent, so your edits stay</td></tr><tr><td><code>paths</code> are not <code>./db/sql</code> and <code>./db/changes</code></td><td>Layout kept; no <code>db/</code> folder is created. A project at <code>./sql</code> and <code>./changes</code> stays there</td></tr><tr><td><code>.gitignore</code> already lists <code>.noorm/state/</code></td><td>Left alone; otherwise the block is appended</td></tr></tbody></table><p><code>db/sql/.gitkeep</code> and <code>db/changes/.gitkeep</code> are listed under <code>Created:</code> on every run for a default layout. They are empty files and are not overwritten.</p><h2 id="how-do-i-run-it-in-ci" tabindex="-1">How do I run it in CI? <a class="header-anchor" href="#how-do-i-run-it-in-ci" aria-label="Permalink to “How do I run it in CI?”">​</a></h2><p><code>--yes</code> skips every prompt but cannot create an identity. Create one first. A checkout that already has <code>.noorm/</code> needs no <code>init</code>, and running it there exits 1, so guard it:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.noorm/identity.key ] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CI_USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CI_EMAIL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .noorm ] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td>No terminal and no <code>--yes</code></td><td><code>Error: noorm init requires an interactive terminal.</code>, exit 2</td></tr><tr><td><code>--yes</code>, but one of <code>identity.key</code>, <code>identity.pub</code>, <code>identity.json</code> is missing</td><td><code>Error: noorm init --yes requires an existing identity at ~/.noorm/identity.{key,pub,json}.</code> with the two commands to fix it, exit 2</td></tr><tr><td>Ctrl+C at a prompt</td><td><code>Cancelled.</code>, exit 0</td></tr><tr><td>Bootstrap fails after the prompts</td><td>The error text, exit 1</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/database/create.html">Creating a database</a>: add a config, create the database, build</li><li><a href="/getting-started/first-build.html">First build</a></li><li><a href="/cli/flags.html">CLI flag conventions</a>: where <code>-c</code> and <code>--yes</code> go</li></ul>`,21)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
